import {readFileSync, writeFileSync} from 'node:fs';
const url = new URL(process.argv[2] || 'http://127.0.0.1:8787/host/');
if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password || url.search || url.hash) {
  throw new Error('Supply a plain HTTP(S) host URL without credentials, query or fragment.');
}
writeFileSync(new URL('../platform/vega/src/host-config.ts', import.meta.url),
  '// Generated by scripts/configure-vega.mjs; laptop relay must remain running.\nexport const HOST_URL = ' + JSON.stringify(url.href) + ';\n');
console.log('Vega host configured: ' + url.href);
const manifestPath = new URL('../platform/vega/manifest.toml', import.meta.url);
let manifest = readFileSync(manifestPath, 'utf8');
manifest = manifest.replace(/\n# BEGIN LOCAL RELAY POLICY[\s\S]*?# END LOCAL RELAY POLICY\n?/, '\n');
if (url.protocol === 'http:') {
  manifest += '\n# BEGIN LOCAL RELAY POLICY\n# Development-only HTTP exception for this configured laptop; no wildcard.\n[network-traffic-policy.cleartext]\nallowed-domains = [' + JSON.stringify(url.hostname) + ']\n# END LOCAL RELAY POLICY\n';
}
writeFileSync(manifestPath, manifest);
